// Validate and extract transcript payload
const body = $input.item.json.body;
if (!body.transcript || !body.client_name) {
  throw new Error('Missing required fields: transcript, client_name');
}
return [{
  json: {
    client_name: body.client_name.trim(),
    company: (body.company || '').trim(),
    transcript: body.transcript,
    call_date: body.call_date || new Date().toISOString().split('T')[0],
    sales_rep: body.sales_rep || 'Derek Moore'
  }
}];

// Parse Claude's JSON output
const raw = $input.item.json.content;
try {
  const parsed = JSON.parse(raw);
  return [{ json: { ...parsed, ...$('Validate & Extract Payload').item.json } }];
} catch (e) {
  throw new Error(`Claude returned invalid JSON: ${raw.slice(0, 200)}`);
}

